mapper.select:
SELECT id, recipient, subject, body, event_type, reference_id, status,
       attempts, next_attempt_at, last_error, created_at, sent_at
FROM mail_delivery
WHERE status IN ('pending', 'sending') AND attempts < 3 AND next_attempt_at <= #{now}
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE mail_delivery
SET status = 'sending', attempts = attempts + 1, next_attempt_at = #{claimUntil}
WHERE id = #{id} AND status IN ('pending', 'sending') AND attempts < 3
  AND next_attempt_at <= #{now}

UPDATE mail_delivery
SET status = 'unknown', last_error = COALESCE(last_error, #{message})
WHERE status = 'sending' AND attempts >= #{maxAttempts} AND next_attempt_at <= #{now}
